export function tmpl_analyze_repos(title: string, description: string, preset: string, repo_a_url: string, repo_a_files: number, repo_a_sha: string, repo_b_url: string, repo_b_files: number, repo_b_sha: string): string {
  // <marrowscript:ext:tmpl_analyze_repos:begin>
  const presetExplanations: Record<string, string> = {
    compat_layer: "build a compatibility layer / adapter mapping A's API surface onto B's idioms",
    combine: "merge A and B into a new unified module that exposes both",
    bridge: "wire A's events / outputs into B's input handlers as glue code",
    port_a_to_b: "reimplement A's primary surface using B's libraries / patterns",
    port_b_to_a: "reimplement B's primary surface using A's libraries / patterns",
    extract: "pull a specific subsystem from A and graft it into B as a new module",
    compare_apis: "produce a diff / report describing how A and B's APIs differ; no code generation",
  };
  const presetGuide = presetExplanations[preset] || "perform the requested operation across the two repos";

  return [
    "You are MarrowForge's repo-pair analyst. The user provided two GitHub",
    "repositories and asked for a specific kind of integration. Read the",
    "request and return ONLY a JSON object on a single line. No prose, no",
    "code fences, no explanation.",
    "",
    "Required keys:",
    "  kind          — one of: component, endpoint, schema, refactor, diagram, full_feature, test",
    "  summary       — one short sentence describing the artifact to produce",
    "  plan          — 3-6 numbered implementation steps, joined with \\n",
    "  target_symbol — the primary exported symbol the artifact will define (PascalCase, ≤ 64 chars)",
    "  complexity    — a number in [0.0, 1.0] (router cutoff is 0.7; multi-repo work usually lands ≥ 0.7)",
    "  ingredients_from_a — a string array of files (paths) to lift / reference from repo A",
    "  ingredients_from_b — a string array of files (paths) to lift / reference from repo B",
    "  graft_point        — a string describing where in B (or where in the new module) the result lives",
    "",
    "The preset tells you HOW to combine the repos. For this request the preset is:",
    "  " + preset + " — " + presetGuide,
    "",
    "Both repos are already cloned and indexed. Their summaries:",
    "  Repo A: " + repo_a_url + " (" + (repo_a_files || "?") + " files, sha " + (repo_a_sha ? repo_a_sha.slice(0, 12) : "?") + ")",
    "  Repo B: " + repo_b_url + " (" + (repo_b_files || "?") + " files, sha " + (repo_b_sha ? repo_b_sha.slice(0, 12) : "?") + ")",
    "",
    "User's request:",
    "  title:       " + title,
    "  description: " + description,
    "",
    "Pick `kind` based on the preset:",
    "  - compat_layer / extract / port_*  →  component",
    "  - bridge                           →  endpoint or full_feature",
    "  - combine                          →  full_feature",
    "  - compare_apis                     →  diagram",
    "",
    "Score `complexity` honestly. Multi-repo work involves at minimum reading",
    "two surfaces and producing one artifact that bridges them; even simple",
    "presets rarely score under 0.6. Architecture-change presets (combine,",
    "port_*) typically score 0.85+ and the router will land them on the",
    "stronger model.",
    "",
    "Example output (single line):",
    "{\"kind\":\"component\",\"summary\":\"Adapter exposing express-rate-limit's API as a drop-in for the user's app\",\"plan\":\"1. Read A's exported config types\\n2. Wrap them in a B-compatible factory\\n3. Add a typed result interface\",\"target_symbol\":\"RateLimitAdapter\",\"complexity\":0.65,\"ingredients_from_a\":[\"src/index.ts\"],\"ingredients_from_b\":[\"src/middleware.ts\"],\"graft_point\":\"B's src/middleware/index.ts\"}",
    "",
    "Return the JSON object now.",
  ].join("\n");
  // <marrowscript:ext:tmpl_analyze_repos:end>
}

/**
 * Extension point: tmpl_generate_report
 * STABLE: implementation required.
 */
export function tmpl_generate_report(plan: string, target_symbol: string, files: string, desired_kind: string, target_path: string, description: string): string {
  // <marrowscript:ext:tmpl_generate_report:begin>
  let planText = plan;
  try {
    const parsed: unknown = typeof plan === "string" ? JSON.parse(plan) : plan;
    if (parsed && typeof parsed === "object") {
      const p = parsed as { plan?: unknown; summary?: unknown };
      const summary = typeof p.summary === "string" ? p.summary : "";
      const planStr = typeof p.plan === "string" ? p.plan : "";
      planText = (summary ? summary + "\n" : "") + planStr;
    }
  } catch {
    // not JSON — leave planText as-is
  }

  let context = "";
  try {
    const parsed: unknown = typeof files === "string" ? JSON.parse(files) : files;
    if (parsed && typeof parsed === "object") {
      const obj = parsed as Record<string, unknown>;
      if (obj.repo_a || obj.repo_b) {
        const a = obj.repo_a as { url?: string; files?: number; sha?: string } | undefined;
        const b = obj.repo_b as { url?: string; files?: number; sha?: string } | undefined;
        const lines: string[] = [];
        if (a) lines.push("Repo A: " + (a.url || "?") + " (" + (a.files ?? "?") + " files, sha " + (a.sha ? a.sha.slice(0, 12) : "?") + ")");
        if (b) lines.push("Repo B: " + (b.url || "?") + " (" + (b.files ?? "?") + " files, sha " + (b.sha ? b.sha.slice(0, 12) : "?") + ")");
        context = lines.join("\n");
      }
    }
  } catch {
    /* leave context empty */
  }

  return [
    "You are MarrowForge's report writer. Produce ONLY a markdown document",
    "that fulfils the request below. No code fences, no prose outside the",
    "markdown, no preamble — just the markdown that should land in the file.",
    "",
    "Rules:",
    "  - Start with a level-1 heading (`# ...`).",
    "  - Use proper markdown: headings, bullet lists, code blocks, tables.",
    "  - For `compare_apis`: include sections \"Overview\", \"Repo A surface\",",
    "    \"Repo B surface\", \"Differences\", and \"Recommendation\".",
    "  - For `migrate`: include sections \"Source state\", \"Target state\",",
    "    \"Step-by-step migration\", and \"Rollback plan\".",
    "  - For `diagram`: a markdown document describing the diagram with an",
    "    embedded mermaid code block (` ```mermaid ... ``` `) the reader can render.",
    "  - Be concise. Quality over volume.",
    "",
    "Desired kind:    " + desired_kind,
    "Target path:     " + target_path,
    "Target symbol:   " + (target_symbol || "(N/A — this is a markdown report)"),
    "",
    "Plan:",
    planText,
    "",
    context ? "Context (read-only — do NOT regenerate these):\n" + context : "",
    "",
    "Original request:",
    description,
    "",
    "Now produce the markdown document.",
  ].filter(Boolean).join("\n");
  // <marrowscript:ext:tmpl_generate_report:end>
}

/**
 * Extension point: tmpl_scope_for_typescript
 * STABLE: implementation required.
 */
export function tmpl_scope_for_typescript(description: string, preset: string, analysis: string): string {
  // <marrowscript:ext:tmpl_scope_for_typescript:begin>
  // The scoping pass. Reads the user's description + the analyst's plan and
  // returns a JSON object the codegen step can consume directly. Three
  // possible feasibility verdicts; each one shapes what the generator does
  // next.
  let analysisText = analysis;
  try {
    const parsed: unknown = typeof analysis === "string" ? JSON.parse(analysis) : analysis;
    if (parsed && typeof parsed === "object") {
      analysisText = JSON.stringify(parsed, null, 2);
    }
  } catch {
    // not JSON — pass through as-is
  }

  return [
    "You are MarrowForge's TypeScript scoping analyst. Your job is to look at",
    "what the user wants and what the prior analyst proposed, then decide",
    "whether the work can actually be done in a single TypeScript file.",
    "",
    "Return ONLY a JSON object on a single line. No prose, no code fences,",
    "no explanation. Required keys:",
    "",
    "  feasibility   one of: \"full\", \"partial\", \"not_achievable\"",
    "  revised_plan  3-6 numbered steps describing what the TS file should do,",
    "                joined with \\n. Replace any non-TS proposals (Python,",
    "                native binaries, GUI frameworks, ML inference) with",
    "                concrete TypeScript-only equivalents — usually \"call",
    "                the system's HTTP API\" or \"shell out to the binary via",
    "                child_process\".",
    "  target_symbol the exported PascalCase symbol the file will define",
    "  complexity    a number in [0.0, 1.0] estimating how much capability",
    "                the scoped task requires (re-score for the TS-only version,",
    "                NOT the original cross-language ambition)",
    "  out_of_scope  array of strings: things the user wanted that this TS",
    "                file deliberately does NOT do, with a one-line reason",
    "                for each. Example: [\"Render images via diffusers — Python",
    "                only; call A1111's HTTP API instead.\"]",
    "  caveats       array of strings: assumptions / dependencies the human",
    "                needs to know about. Example: [\"Assumes A1111 is running",
    "                with --api flag\", \"LM Studio must expose model on /v1\"]",
    "",
    "Feasibility decision tree:",
    "",
    "  full           — A single TS file can fully implement the request",
    "                   using Node builtins + standard `fetch`. The user gets",
    "                   exactly what they asked for. Use this for: HTTP",
    "                   adapters, type-safe API wrappers, glue between two",
    "                   HTTP services, request/response transformations,",
    "                   utility libraries.",
    "",
    "  partial        — TS can do part of the job but not all of it. Common",
    "                   reasons: the request needs a Python ML library, a",
    "                   native binary, a GUI framework, or a runtime feature",
    "                   TS doesn't have. The TS file does what it CAN; the",
    "                   rest goes in `out_of_scope` for the human to handle.",
    "                   Example: \"compatibility layer for Stable Diffusion +",
    "                   LM Studio\" → TS can do the LM Studio half and call",
    "                   A1111's HTTP API; it can't run diffusion itself.",
    "",
    "  not_achievable — the request fundamentally can't be a TS file. Common",
    "                   reasons: the user wants a Python module, a native",
    "                   plugin, a Gradio extension, a kernel-level component.",
    "                   In this case set revised_plan to describe a stub TS",
    "                   file that documents WHY the work can't be done in TS",
    "                   and what to do instead. The codegen step will produce",
    "                   that documented stub.",
    "",
    "Common cross-language scenarios — bias toward partial, not not_achievable:",
    "",
    "  - Python codebase + JS/TS service       → partial: TS HTTP client for the Python service",
    "  - Native binary (ffmpeg, git, etc.)     → partial: TS wrapper using child_process.execFile",
    "  - GUI framework (Gradio, Tk, etc.)      → partial: TS skips the GUI; exposes core logic",
    "  - ML inference (torch, diffusers)       → partial: TS calls inference server's HTTP API",
    "  - Kernel / driver / native plugin       → not_achievable; document and stub",
    "  - Anything that's purely a CLI tool     → partial: TS shell wrapper",
    "",
    "Example outputs:",
    "",
    "  Full:",
    "    {\"feasibility\":\"full\",\"revised_plan\":\"1. Define typed RequestInit\\n2. Wrap fetch\\n3. Add error mapping\",\"target_symbol\":\"LmStudioClient\",\"complexity\":0.4,\"out_of_scope\":[],\"caveats\":[\"Assumes LM Studio is running on configured endpoint\"]}",
    "",
    "  Partial:",
    "    {\"feasibility\":\"partial\",\"revised_plan\":\"1. Build typed client for A1111's /sdapi/v1/txt2img\\n2. Build typed client for LM Studio's /v1/chat/completions\\n3. Combine into orchestrator that enhances prompts via LLM then calls SD\",\"target_symbol\":\"PromptEnhancingDiffuser\",\"complexity\":0.7,\"out_of_scope\":[\"Running diffusion locally — Python-only; this file calls A1111's HTTP API instead\",\"Gradio UI — out of scope for a single TS file\"],\"caveats\":[\"A1111 must be running with --api\",\"LM Studio must expose chat-completions on /v1\"]}",
    "",
    "  Not achievable:",
    "    {\"feasibility\":\"not_achievable\",\"revised_plan\":\"1. Export a documented stub explaining why TS cannot host a Gradio extension\\n2. List the file structure the user would need in Python (extensions/lmstudio-bridge/)\\n3. Provide a starter Python skeleton as a string export the user can copy out\",\"target_symbol\":\"GradioExtensionStub\",\"complexity\":0.2,\"out_of_scope\":[\"Gradio is a Python framework; A1111 extensions must be Python modules\",\"This file documents the situation rather than pretending to implement it\"],\"caveats\":[\"To actually build this, create a Python file in A1111's extensions/ folder, not a TS file\"]}",
    "",
    "User's request:",
    "  preset:      " + preset,
    "  description: " + description,
    "",
    "Prior analyst's plan:",
    analysisText,
    "",
    "Return the JSON object now.",
  ].join("\n");
  // <marrowscript:ext:tmpl_scope_for_typescript:end>
}
